CREATE TYPE public.app_role AS ENUM ('admin','staff');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_number text NOT NULL UNIQUE, request_id uuid NOT NULL UNIQUE, customer_name text NOT NULL, phone text NOT NULL, address text NOT NULL, postal_code text NOT NULL, notes text NOT NULL DEFAULT '', items jsonb NOT NULL, total integer NOT NULL, status text NOT NULL DEFAULT 'received' CHECK(status IN ('received','preparing','out_for_delivery','delivered','cancelled')), payment_method text NOT NULL DEFAULT 'cod' CHECK(payment_method IN ('cod','razorpay')), payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','pending','paid','failed')), notification_status text NOT NULL DEFAULT 'not_configured', eta_minutes integer NOT NULL DEFAULT 60, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.orders TO authenticated;
GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_read_orders ON public.orders FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE POLICY staff_update_orders ON public.orders FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE INDEX orders_created_at_idx ON public.orders(created_at DESC);